#!/usr/bin/env node
/**
 * beforeShellExecution — Cursor-only check for AI attribution in git commit messages.
 *
 * Denies only `git commit` commands whose message contains tool trailers
 * (Co-authored-by / Assisted-by / Generated-by / tool Signed-off-by) or
 * “generated by AI” phrasing. Fails open for every other command.
 * Never gates writes to app/, lib/, or components/.
 *
 * Canonical rule for all agents (including non-Cursor) lives in docs/AGENTS.md.
 */
"use strict";

const TOOL =
  "Cursor|Claude|Copilot|Codex|Grok|ChatGPT|OpenAI|Anthropic|Gemini|Composer|assistant|\\bAI\\b|cursoragent|@cursor\\.|github-copilot";

function readStdin() {
  try {
    return require("fs").readFileSync(0, "utf8");
  } catch {
    return "";
  }
}

function allow() {
  process.stdout.write(JSON.stringify({ permission: "allow" }));
}

function deny(agentMessage, userMessage) {
  process.stdout.write(
    JSON.stringify({
      permission: "deny",
      agent_message: agentMessage,
      user_message: userMessage || agentMessage,
    }),
  );
}

function isGitCommit(command) {
  return /\bgit(?:\.exe)?\s+(?:-C\s+\S+\s+)*commit\b/i.test(command);
}

/**
 * Best-effort extract of commit message text from common agent shell forms:
 * -m "..." / -m '...' / multiple -m / HEREDOC bodies.
 */
function extractCommitMessage(command) {
  const parts = [];

  // Double-quoted -m (may contain real newlines or literal \n)
  const dq = /(?:^|\s)-m\s+"((?:\\.|[^"\\])*)"/g;
  let match;
  while ((match = dq.exec(command)) !== null) {
    parts.push(match[1]);
  }

  // Single-quoted -m
  const sq = /(?:^|\s)-m\s+'([^']*)'/g;
  while ((match = sq.exec(command)) !== null) {
    parts.push(match[1]);
  }

  // HEREDOC bodies (bash / PowerShell-ish agent forms)
  const heredoc = /<<['"]?EOF['"]?\r?\n([\s\S]*?)\r?\nEOF/gi;
  while ((match = heredoc.exec(command)) !== null) {
    parts.push(match[1]);
  }

  // Bare -m token (no quotes)
  const bare = /(?:^|\s)-m\s+([^\s"'$\\-][^\s]*)/g;
  while ((match = bare.exec(command)) !== null) {
    parts.push(match[1]);
  }

  return parts.join("\n");
}

function normalizeMessage(message) {
  return String(message || "")
    .replace(/\\n/g, "\n")
    .replace(/\\t/g, "\t");
}

function messageHasForbiddenAttribution(rawMessage) {
  const message = normalizeMessage(rawMessage);
  if (!message.trim()) return false;

  // Assisted-by / Generated-by trailers (any value) — tool attribution
  if (/(?:^|\n)\s*(Assisted-by|Generated-by)\s*:/i.test(message)) {
    return true;
  }

  // Co-authored-by naming a tool/bot
  if (
    new RegExp(
      String.raw`(?:^|\n)\s*Co-authored-by\s*:.*(?:` + TOOL + String.raw`)`,
      "i",
    ).test(message)
  ) {
    return true;
  }

  // Signed-off-by naming a tool/bot (human DCO Sign-offs are allowed)
  if (
    new RegExp(
      String.raw`(?:^|\n)\s*Signed-off-by\s*:.*(?:` + TOOL + String.raw`)`,
      "i",
    ).test(message)
  ) {
    return true;
  }

  if (
    /generated\s+by\s+(an?\s+)?(ai|cursor|claude|copilot|codex|grok|chatgpt|assistant)/i.test(
      message,
    )
  ) {
    return true;
  }

  return false;
}

function main() {
  let input;
  try {
    const raw = readStdin();
    input = raw ? JSON.parse(raw) : {};
  } catch {
    allow();
    return;
  }

  const command = String(input.command || "");
  if (!command || !isGitCommit(command)) {
    allow();
    return;
  }

  const message = extractCommitMessage(command);
  // If we cannot see a message body (editor-only commit), fail open
  if (!message.trim()) {
    allow();
    return;
  }

  if (!messageHasForbiddenAttribution(message)) {
    allow();
    return;
  }

  deny(
    "Blocked: commit message attributes work to an AI or tool. Linaw forbids Co-authored-by / Assisted-by / Generated-by / tool Signed-off-by trailers and “generated by AI” comments. Use a normal human commit message. See docs/AGENTS.md (No AI attribution).",
    "Linaw policy: no AI/tool attribution in commit messages.",
  );
}

try {
  main();
} catch {
  allow();
}
